/** 
 * Increases the volume by one for the current audio stream. It will be ignored if the current volume is equal to  {@link #getMaxVolume()}.
 */
public void increaseVolume(){
  if (volume >= getMaxVolume()) {
    return;
  }
  try {
    audioManager.adjustStreamVolume(streamType, AudioManager.ADJUST_RAISE, VOLUME_FLAGS);
    updateVolumeAndNotifyIfChanged();
  } catch (RuntimeException e) {
    e.printStackTrace();
  }
}
